package run.ikaros.finance; import java.math.BigDecimal; import java.time.Instant; import java.util.UUID; import org.springframework.stereotype.Service; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; import run.ikaros.common.NotFoundException; @Service public class ExchangeRateService{private final LedgerRepository ledgers;private final ExchangeRateRepository rates;public ExchangeRateService(LedgerRepository l,ExchangeRateRepository r){ledgers=l;rates=r;}public Mono<ExchangeRateView> create(UUID a,UUID l,CreateExchangeRateRequest q){if(q.rate().signum()<=0)return Mono.error(new IllegalArgumentException("汇率必须大于 0"));return own(a,l).flatMap(x->rates.save(new ExchangeRateEntity(null,l,a,q.fromCurrency().toUpperCase(),q.toCurrency().toUpperCase(),q.rate(),q.effectiveAt(),q.provider(),q.source(),Instant.now(),null))).map(this::view);}public Flux<ExchangeRateView> list(UUID a,UUID l){return own(a,l).flatMapMany(x->rates.findAllByLedgerIdAndOwnerIdOrderByEffectiveAtDesc(l,a).map(this::view));}private Mono<LedgerEntity> own(UUID a,UUID l){return ledgers.findById(l).filter(x->x.ownerId().equals(a)).switchIfEmpty(Mono.error(new NotFoundException("Ledger 不存在或无权访问")));}private ExchangeRateView view(ExchangeRateEntity x){return new ExchangeRateView(x.id(),x.fromCurrency(),x.toCurrency(),x.rate(),x.effectiveAt(),x.provider(),x.source());}}
